<template>
  <section class="page-panel" v-loading="loading"><h1 class="page-heading">{{ templateId ? '编辑运费模板' : '新建运费模板' }}</h1><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="feedback" /><el-alert v-if="notice" :title="notice" role="status" aria-live="polite" aria-atomic="true" type="success" :closable="false" show-icon class="feedback" />
    <el-form v-if="loaded" label-position="top" @submit.native.prevent="save"><div class="form-grid"><el-form-item label="模板名称" :for="fieldId('freight-name')"><el-input v-model="form.name" maxlength="255" :disabled="busy" :id="fieldId('freight-name')" :label="'模板名称'" /></el-form-item><el-form-item label="计费方式" :for="fieldId('freight-type')"><el-select v-model="form.type" :disabled="busy" :id="fieldId('freight-type')" v-control-label="'计费方式'"><el-option :value="1" label="按件数" /><el-option :value="2" label="按重量（kg）" /><el-option :value="3" label="按体积（m³）" /></el-select></el-form-item><el-form-item label="排序" :for="fieldId('freight-sort')"><el-input-number v-model="form.sort" :precision="0" :min="-2147483648" :max="2147483647" :disabled="busy" :label="'排序'" v-control-label="{ id: fieldId('freight-sort'), label: '排序' }" /></el-form-item></div>
      <h2 class="section-heading">配送运费规则</h2><div v-for="(rule, index) in form.region_info" :key="index" class="rule-block"><el-form-item label="适用地域" :for="nationwide(rule.region) ? undefined : fieldId('region-' + index + '-place')"><p v-if="nationwide(rule.region)" class="field-note">默认全国</p><region-picker v-else :control-id="fieldId('region-' + index + '-place')" :control-label="'第' + (index + 1) + '项运费规则适用地域'" v-model="rule.region" :cities="cities" :disabled="busy" /></el-form-item><div class="region-fields"><el-form-item :label="quantityLabel('首')" :for="fieldId('region-' + index + '-first')"><el-input v-model="rule.first" inputmode="decimal" :disabled="busy" :id="fieldId('region-' + index + '-first')" :label="'第' + (index + 1) + '项运费规则 ' + quantityLabel('首')" /></el-form-item><el-form-item label="首费（元）" :for="fieldId('region-' + index + '-price')"><el-input v-model="rule.price" inputmode="decimal" :disabled="busy" :id="fieldId('region-' + index + '-price')" :label="'第' + (index + 1) + '项运费规则 首费（元）'" /></el-form-item><el-form-item :label="quantityLabel('续')" :for="fieldId('region-' + index + '-continue')"><el-input v-model="rule.continue" inputmode="decimal" :disabled="busy" :id="fieldId('region-' + index + '-continue')" :label="'第' + (index + 1) + '项运费规则 ' + quantityLabel('续')" /></el-form-item><el-form-item label="续费（元）" :for="fieldId('region-' + index + '-continue-price')"><el-input v-model="rule.continue_price" inputmode="decimal" :disabled="busy" :id="fieldId('region-' + index + '-continue-price')" :label="'第' + (index + 1) + '项运费规则 续费（元）'" /></el-form-item></div><el-button v-if="!nationwide(rule.region)" :disabled="busy" size="small" @click="form.region_info.splice(index, 1)">移除此规则</el-button></div><el-button :disabled="busy || form.region_info.length >= 200" @click="addRegion">添加地域运费</el-button>
      <h2 class="section-heading">指定包邮</h2><el-switch aria-label="启用指定包邮" v-control-label="'启用指定包邮'" v-model="form.appoint" :active-value="1" :inactive-value="0" active-text="启用指定包邮" :disabled="busy" /><div v-if="form.appoint"><div v-for="(rule, index) in form.appoint_info" :key="index" class="rule-block"><el-form-item label="包邮地域" :for="fieldId('free-' + index + '-place')"><region-picker :control-id="fieldId('free-' + index + '-place')" :control-label="'第' + (index + 1) + '项包邮规则地域'" v-model="rule.place" :cities="cities" :disabled="busy" /></el-form-item><div class="form-grid"><el-form-item :label="quantityLabel('满')" :for="fieldId('free-' + index + '-num')"><el-input v-model="rule.a_num" inputmode="decimal" :disabled="busy" :id="fieldId('free-' + index + '-num')" :label="'第' + (index + 1) + '项包邮规则 ' + quantityLabel('满')" /></el-form-item><el-form-item label="满金额（元）" :for="fieldId('free-' + index + '-price')"><el-input v-model="rule.a_price" inputmode="decimal" :disabled="busy" :id="fieldId('free-' + index + '-price')" :label="'第' + (index + 1) + '项包邮规则 满金额（元）'" /></el-form-item></div><el-button size="small" :disabled="busy" @click="form.appoint_info.splice(index, 1)">移除包邮规则</el-button></div><el-button :disabled="busy || form.appoint_info.length >= 200" @click="form.appoint_info.push({ place: [], a_num: '0.00', a_price: '0.00' })">添加包邮规则</el-button></div>
      <h2 class="section-heading">不配送地域</h2><el-switch aria-label="启用不配送地域" v-control-label="'启用不配送地域'" v-model="form.no_delivery" :active-value="1" :inactive-value="0" active-text="启用不配送地域" :disabled="busy" /><div v-if="form.no_delivery"><div v-for="(rule, index) in form.no_delivery_info" :key="index" class="rule-block"><el-form-item label="不配送地域" :for="fieldId('blocked-' + index + '-place')"><region-picker :control-id="fieldId('blocked-' + index + '-place')" :control-label="'第' + (index + 1) + '项不配送规则地域'" v-model="rule.place" :cities="cities" :disabled="busy" /></el-form-item><el-button size="small" :disabled="busy" @click="form.no_delivery_info.splice(index, 1)">移除此地域</el-button></div><el-button :disabled="busy || form.no_delivery_info.length >= 200" @click="form.no_delivery_info.push({ place: [] })">添加不配送地域</el-button></div>
      <div class="actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="busy">保存模板</el-button><el-button :disabled="busy" @click="$router.push('/freight')">返回列表</el-button></div>
    </el-form>
  </section>
</template>
<script>
import { fieldNames } from '../../accessibility';
import { api } from '../../api';
import { recordId } from '../../domain/product';
import { blankFreight, freightFromDetail, freightWrite, regionRule } from '../../domain/freight';
import RegionPicker from '../../components/RegionPicker.vue';
export default {
  mixins: [fieldNames],
  components: { RegionPicker }, data: () => ({ templateId: null, form: blankFreight(), cities: [], loading: false, loaded: false, busy: false, error: '', notice: '' }),
  created() { this.load(); }, watch: { '$route.params.id'() { this.load(); } },
  methods: {
    nationwide(value) { return !Array.isArray(value) && value.city_id === 0; }, quantityLabel(prefix) { return prefix + (this.form.type === 1 ? '件数' : this.form.type === 2 ? '重量（kg）' : '体积（m³）'); }, addRegion() { this.form.region_info.push(regionRule()); },
    async load() {
      this.loading = true; this.loaded = false; this.error = ''; this.notice = '';
      try { this.templateId = this.$route.params.id ? recordId(this.$route.params.id) : null; const cities = await api.freightCities(); if (!Array.isArray(cities.list)) throw new Error('城市列表返回不完整'); this.cities = cities.list; this.form = this.templateId ? freightFromDetail(await api.freightTemplate(this.templateId)) : blankFreight(); this.loaded = true; }
      catch (error) { this.error = error.message; } finally { this.loading = false; }
    },
    async save() {
      if (this.busy) return; this.busy = true; this.error = ''; this.notice = ''; let saved = false;
      try { const result = await api.saveFreight(this.templateId, freightWrite(this.form)); this.templateId = recordId(result.id); saved = true; const actual = await api.freightTemplate(this.templateId); this.form = freightFromDetail(actual); this.notice = '运费模板已保存'; if (this.$route.name === 'freight-new') await this.$router.replace('/freight/' + this.templateId + '/edit'); }
      catch (error) { this.error = (saved ? '模板已保存，详情重新读取未完成：' : '') + error.message; } finally { this.busy = false; }
    },
  },
};
</script>
